const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{pathToFileURL}=require('node:url'),{chromium}=require('playwright');
const outputDir=path.resolve(__dirname,'../../.planning/session-desk-tests');fs.mkdirSync(outputDir,{recursive:true});
const dir=path.resolve(__dirname,'../../实用小工具/Codex会话交接评估');
const source=fs.readFileSync(path.join(dir,'browser-compatibility-check.html'),'utf8').replace(/\r\n/g,'\n');const parser=source.slice(source.indexOf('function parseCompatibility('),source.indexOf('window.parseCompatibility='));assert.ok(fs.readFileSync(path.join(dir,'session-desk-validation.html'),'utf8').replace(/\r\n/g,'\n').includes(parser),'original parser unchanged');
(async()=>{const browser=await chromium.launch({channel:'msedge',headless:true});try{const page=await browser.newPage({acceptDownloads:true});let requests=0;const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>{if(/^https?:/.test(r.url()))requests++;});await page.goto(pathToFileURL(path.join(dir,'session-desk-validation.html')).href);assert.deepEqual(errors,[]);
const checks=[];const ok=name=>checks.push(name),id=n=>'00000000-0000-0000-0000-'+String(n).padStart(12,'0');
const fixture=await page.evaluate(()=>({one:generateSamples(tasks[0].id),two:generateSamples(tasks[1].id)}));const file=(text,name='a.jsonl')=>({name,mimeType:'application/x-ndjson',buffer:Buffer.from(text)});
const choose=async(files,wait=true)=>{const event=page.waitForEvent('filechooser');await page.locator('#choose').click();await(await event).setFiles(files);if(wait)await page.waitForFunction(()=>!document.getElementById('choose').disabled);};
await page.locator('#search').fill('灯塔');assert.equal(await page.locator('.task').count(),1);await page.locator('.star').click();await page.locator('#search').fill('');await page.locator('#onlyFav').check();assert.equal(await page.locator('.task').count(),1);await page.locator('#onlyFav').uncheck();ok('search and memory favorites');
await choose([file(fixture.one.a),file(fixture.one.b,'b.jsonl')]);assert.equal(await page.locator('#tokens').textContent(),'130');assert.equal(await page.locator('#turns').textContent(),'1');ok('selected two segments summary');
await page.locator('#details summary').click();assert.match(await page.locator('#report').textContent(),/"baseline": 1/);ok('detailed report');
await choose([file(fixture.one.a)]);assert.equal(await page.locator('#tokens').textContent(),'100');await choose([file(fixture.one.a)]);assert.equal(await page.locator('#tokens').textContent(),'100');ok('replace and repeat no accumulation');
await choose([file(fixture.one.cut)]);assert.equal(await page.locator('#stats').isHidden(),true);assert.equal(await page.locator('#state').getAttribute('data-state'),'blocked');ok('truncation clears summary');
await page.locator(`[data-task="${id(2)}"]`).click();assert.equal(await page.locator('#stats').isHidden(),true);await choose([file(fixture.one.a)]);assert.match(await page.locator('#notice').textContent(),/不属于当前任务/);ok('same-name task isolation');
await choose([file(fixture.two.a),file(fixture.two.b,'b.jsonl')]);assert.equal(await page.locator('#tokens').textContent(),'130');ok('second task own files');
await page.evaluate(()=>{window.realRead=File.prototype.arrayBuffer;File.prototype.arrayBuffer=function(){return new Promise(resolve=>{window.release=()=>window.realRead.call(this).then(resolve);});};});await choose([file(fixture.two.a)],false);await page.waitForFunction(()=>!!window.release);assert.equal(await page.locator('#stats').isHidden(),true);ok('loading invalidates result');
await page.locator(`[data-task="${id(1)}"]`).click();await page.evaluate(async()=>{await window.release();File.prototype.arrayBuffer=window.realRead;});await page.waitForTimeout(50);assert.equal(await page.locator('#state').getAttribute('data-state'),'blocked');await page.locator(`[data-task="${id(2)}"]`).click();assert.equal(await page.locator('#state').getAttribute('data-state'),'cancelled');ok('task switch cancels old read');
await page.evaluate(()=>{File.prototype.arrayBuffer=async()=>{throw Error('synthetic failure');};});await choose([file(fixture.two.a)]);assert.equal(await page.locator('#state').getAttribute('data-state'),'failed');assert.equal(await page.locator('#stats').isHidden(),true);await page.evaluate(()=>{File.prototype.arrayBuffer=window.realRead;});ok('read failure no stale result');
await choose([file(fixture.two.a)]);assert.equal(await page.locator('#tokens').textContent(),'100');ok('retry recovers');
await choose([{name:'large.jsonl',mimeType:'text/plain',buffer:Buffer.alloc(2*1048576+1)}]);assert.match(await page.locator('#notice').textContent(),/超过/);assert.equal(await page.locator('#stats').isHidden(),true);ok('single size limit');
const corpus=JSON.parse(fs.readFileSync(path.join(dir,'compatibility-fixtures.json'),'utf8'));
for(const c of corpus.cases){const r=await page.evaluate(({s,id})=>analyzeForTask(s.map(x=>({name:x.name,bytes:new TextEncoder().encode(x.text)})),id),{s:c.segments,id:id(1)});if(c.name==='wrong-internal-id'){assert.equal(r.reason,'task_mismatch');}else if(c.name==='malformed-token-record'){assert.equal(r.stage,'integrity_blocked');}else if(c.comparison.browser.ok){assert.deepEqual(r.result,c.comparison.browser.result,c.name);}else assert.equal(r.reason,c.comparison.browser.error,c.name);}ok('20-case corpus with strict task identity');
// Exactly 16 MiB across eight valid 2 MiB segments; no real files involved.
const start=Date.now();const maximum=await page.evaluate(id=>{const segments=[];for(let i=0;i<8;i++){const meta={type:'session_meta',timestamp:new Date(Date.UTC(2025,0,1,0,i)).toISOString(),payload:{id,synthetic_test:true}};const empty=JSON.stringify(meta)+'\n'+JSON.stringify({type:'response_item',payload:{padding:''}});const text=empty.slice(0,-3)+'x'.repeat(2*1048576-new TextEncoder().encode(empty).length)+empty.slice(-3);segments.push({name:i+'.jsonl',bytes:new TextEncoder().encode(text)});}return analyzeForTask(segments,id);},id(2));assert.equal(maximum.stage,'parsed');assert.equal(maximum.result.segments,8);const maxMs=Date.now()-start;ok('16 MiB aggregate boundary');
const limits=await page.evaluate(id=>({count:analyzeForTask(Array.from({length:33},(_,i)=>({name:i+'.jsonl',bytes:new Uint8Array(0)})),id),total:analyzeForTask(Array.from({length:9},(_,i)=>({name:i+'.jsonl',bytes:new Uint8Array(2*1048576)})),id)}),id(2));assert.equal(limits.count.reason,'size_limit');assert.equal(limits.total.reason,'size_limit');ok('segment count and aggregate excess blocked');
await page.locator('summary').first().click();for(const kind of ['a','b','cut']){const pending=page.waitForEvent('download');await page.locator(`[data-sample="${kind}"]`).click();const download=await pending;const target=path.join(outputDir,download.suggestedFilename());await download.saveAs(target);assert.equal(fs.readFileSync(target,'utf8'),fixture.two[kind]);}ok('downloads belong to selected task');
await choose([file(fixture.two.a),file(fixture.two.b,'b.jsonl')]);await page.screenshot({path:path.join(outputDir,'desktop.png'),fullPage:true});await page.setViewportSize({width:390,height:844});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await page.screenshot({path:path.join(outputDir,'mobile.png'),fullPage:true});ok('390px no overflow');
await page.locator('#clear').click();assert.equal(await page.locator('#stats').isHidden(),true);await page.reload();assert.equal(await page.locator('[aria-pressed=true]').count(),0);assert.equal(await page.locator('#stats').isHidden(),true);ok('clear and reload remove state');assert.equal(requests,0);assert.deepEqual(errors,[]);ok('no HTTP or page errors');
fs.writeFileSync(path.join(outputDir,'result.json'),JSON.stringify({browser:browser.version(),count:checks.length,checks,maxMs,requests,errors},null,2));console.log(JSON.stringify({count:checks.length,checks,maxMs,requests,errors}));
}finally{await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
